('tv1-bai-09', 'tieng-viet', 1, 2, 'Âm và chữ: o, ô, d, đ, ơ', 9, 'Ơ ơ, dấu ngã', 'Ơơ', 'Học chữ ơ và dấu ngã, đánh vần bơ, cờ', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu đều có âm ơ.","visual":{"kind":"scene","emoji":["👩","👧","🥑"],"sentence":"Bé theo mẹ đi chợ mua bơ.","highlight":["chợ","bơ"]}},{"text":"Chữ ơ là chữ o thêm râu. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Ơ","ơ"],"say":"ơ"}},{"text":"Bé đánh vần: bờ, ơ, bơ. Cờ, ơ, cơ, huyền, cờ.","visual":{"kind":"spell","steps":[{"parts":["b","ơ"],"result":"bơ","say":"bờ, ơ, bơ"},{"parts":["c","ơ"],"result":"cơ","say":"cờ, ơ, cơ"},{"parts":["cơ","◌̀ huyền"],"result":"cờ","say":"cơ, huyền, cờ"}]}},{"text":"Dấu ngã trông như làn sóng nhỏ. Dê thêm dấu ngã thành dễ, đơ thêm dấu ngã thành đỡ.","visual":{"kind":"spell","steps":[{"parts":["dê","◌̃ ngã"],"result":"dễ","say":"dê, ngã, dễ"},{"parts":["đơ","◌̃ ngã"],"result":"đỡ","say":"đơ, ngã, đỡ"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🚩","word":"cờ"},{"emoji":"🥑","word":"bơ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bé có cờ đỏ.","highlight":["cờ"]}}]'::jsonb),
('tv1-bai-10', 'tieng-viet', 1, 2, 'Âm và chữ: o, ô, d, đ, ơ', 10, 'Ôn tập', 'Ôn', 'Ôn lại chữ o, ô, d, đ, ơ và dấu hỏi, dấu nặng, dấu ngã', '[{"text":"Bé đã học thêm năm chữ: o, ô, d, đ, ơ. Bé bấm để nghe lại.","visual":{"kind":"letter","letters":["o","ô","d","đ","ơ"],"say":"o, ô, dờ, đờ, ơ"}},{"text":"Bé nhớ lại ba dấu mới: dấu hỏi, dấu nặng, dấu ngã.","visual":{"kind":"spell","steps":[{"parts":["co","◌̉ hỏi"],"result":"cỏ","say":"co, hỏi, cỏ"},{"parts":["co","◌̣ nặng"],"result":"cọ","say":"co, nặng, cọ"},{"parts":["dê","◌̃ ngã"],"result":"dễ","say":"dê, ngã, dễ"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🐄","word":"bò"},{"emoji":"☔","word":"ô"},{"emoji":"🐐","word":"dê"},{"emoji":"🚩","word":"cờ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bờ đê có bò, có dê.","highlight":[]}}]'::jsonb),
('tv1-bai-11', 'tieng-viet', 1, 3, 'Âm và chữ: i, k, h, l, u, ư, ch, kh', 11, 'I i, K k', 'Ik', 'Học chữ i, k, đánh vần bí, kì', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có chữ i hoặc chữ k.","visual":{"kind":"scene","emoji":["👧","📏","📒"],"sentence":"Bé kẻ ô li thật kĩ.","highlight":["kẻ","li","kĩ"]}},{"text":"Chữ i có một chấm nhỏ ở trên. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["I","i"],"say":"i"}},{"text":"Chữ k đọc là ca. Chữ k chỉ đứng trước i, e, ê. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["K","k"],"say":"ca"}},{"text":"Bé đánh vần: bờ, i, bi, sắc, bí. Ca, i, ki, huyền, kì.","visual":{"kind":"spell","steps":[{"parts":["b","i"],"result":"bi","say":"bờ, i, bi"},{"parts":["bi","◌́ sắc"],"result":"bí","say":"bi, sắc, bí"},{"parts":["k","i"],"result":"ki","say":"ca, i, ki"},{"parts":["ki","◌̀ huyền"],"result":"kì","say":"ki, huyền, kì"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🎃","word":"bí"},{"emoji":"🦎","word":"kì đà"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Kì đà bò ở bờ đê.","highlight":["kì"]}}]'::jsonb),
('tv1-bai-12', 'tieng-viet', 1, 3, 'Âm và chữ: i, k, h, l, u, ư, ch, kh', 12, 'H h, L l', 'Hl', 'Học chữ h, l, đánh vần hổ, lá', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm h hoặc âm l.","visual":{"kind":"scene","emoji":["👧","👵","🍂"],"sentence":"Bé cùng bà ra hồ, lá vàng rơi lả tả.","highlight":["hồ","lá","lả"]}},{"text":"Chữ h đọc là hờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["H","h"],"say":"hờ"}},{"text":"Chữ l đọc là lờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["L","l"],"say":"lờ"}},{"text":"Bé đánh vần: hờ, ô, hô, hỏi, hổ. Lờ, a, la, sắc, lá.","visual":{"kind":"spell","steps":[{"parts":["h","ô"],"result":"hô","say":"hờ, ô, hô"},{"parts":["hô","◌̉ hỏi"],"result":"hổ","say":"hô, hỏi, hổ"},{"parts":["l","a"],"result":"la","say":"lờ, a, la"},{"parts":["la","◌́ sắc"],"result":"lá","say":"la, sắc, lá"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🐯","word":"hổ"},{"emoji":"🍁","word":"lá"},{"emoji":"🍐","word":"lê"},{"emoji":"🤡","word":"hề"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Dì Hà bổ lê.","highlight":["hà","lê"]}}]'::jsonb),
('tv1-bai-13', 'tieng-viet', 1, 3, 'Âm và chữ: i, k, h, l, u, ư, ch, kh', 13, 'U u, Ư ư', 'Uư', 'Học chữ u, ư, đánh vần cú, dữ', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm u hoặc âm ư.","visual":{"kind":"scene","emoji":["🦉","👀","👧"],"sentence":"Chú cú có đôi mắt to tròn, cứ nhìn bé mãi.","highlight":["chú","cú","cứ"]}},{"text":"Đây là chữ u: U hoa và u thường. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["U","u"],"say":"u"}},{"text":"Chữ ư là chữ u thêm râu. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Ư","ư"],"say":"ư"}},{"text":"Bé đánh vần: cờ, u, cu, sắc, cú. Dờ, ư, dư, ngã, dữ.","visual":{"kind":"spell","steps":[{"parts":["c","u"],"result":"cu","say":"cờ, u, cu"},{"parts":["cu","◌́ sắc"],"result":"cú","say":"cu, sắc, cú"},{"parts":["d","ư"],"result":"dư","say":"dờ, ư, dư"},{"parts":["dư","◌̃ ngã"],"result":"dữ","say":"dư, ngã, dữ"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🦉","word":"cú"},{"emoji":"🐅","word":"hổ dữ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bé đi đò, cụ cứ lo.","highlight":["cụ","cứ"]}}]'::jsonb),
('tv1-bai-14', 'tieng-viet', 1, 3, 'Âm và chữ: i, k, h, l, u, ư, ch, kh', 14, 'Ch ch, Kh kh', 'Ch', 'Học chữ ch, kh, đánh vần chó, khỉ', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm ch hoặc âm kh.","visual":{"kind":"scene","emoji":["🐒","🐶","😆"],"sentence":"Chú khỉ con trêu chú chó, cả nhà cười khúc khích.","highlight":["chú","khỉ","chó","khúc","khích"]}},{"text":"Chữ ch ghép từ c và h, đọc là chờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Ch","ch"],"say":"chờ"}},{"text":"Chữ kh ghép từ k và h, đọc là khờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Kh","kh"],"say":"khờ"}},{"text":"Bé đánh vần: chờ, o, cho, sắc, chó. Khờ, i, khi, hỏi, khỉ.","visual":{"kind":"spell","steps":[{"parts":["ch","o"],"result":"cho","say":"chờ, o, cho"},{"parts":["cho","◌́ sắc"],"result":"chó","say":"cho, sắc, chó"},{"parts":["kh","i"],"result":"khi","say":"khờ, i, khi"},{"parts":["khi","◌̉ hỏi"],"result":"khỉ","say":"khi, hỏi, khỉ"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🐶","word":"chó"},{"emoji":"🐒","word":"khỉ"},{"emoji":"🧵","word":"chỉ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bà kho cá, chị đi chợ.","highlight":["kho","chị","chợ"]}}]'::jsonb),
('tv1-bai-15', 'tieng-viet', 1, 3, 'Âm và chữ: i, k, h, l, u, ư, ch, kh', 15, 'Ôn tập', 'Ôn', 'Ôn lại chữ i, k, h, l, u, ư, ch, kh', '[{"text":"Bé đã học thêm tám chữ. Đây là bốn chữ đầu: i, k, h, l. Bé bấm để nghe lại.","visual":{"kind":"letter","letters":["i","k","h","l"],"say":"i, ca, hờ, lờ"}},{"text":"Còn đây là bốn chữ sau: u, ư, ch, kh. Bé bấm để nghe lại.","visual":{"kind":"letter","letters":["u","ư","ch","kh"],"say":"u, ư, chờ, khờ"}},{"text":"Bé nhớ: k đứng trước i, e, ê, như kẻ. Còn c đứng trước a, o, ô, ơ, u, ư, như cú.","visual":{"kind":"spell","steps":[{"parts":["k","e"],"result":"ke","say":"ca, e, ke"},{"parts":["ke","◌̉ hỏi"],"result":"kẻ","say":"ke, hỏi, kẻ"},{"parts":["c","u"],"result":"cu","say":"cờ, u, cu"},{"parts":["cu","◌́ sắc"],"result":"cú","say":"cu, sắc, cú"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🎃","word":"bí"},{"emoji":"🍐","word":"lê"},{"emoji":"🦉","word":"cú"},{"emoji":"🐒","word":"khỉ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Chú khỉ đi chợ. Chợ có lê, có bí.","highlight":[]}}]'::jsonb),
('tv1-bai-16', 'tieng-viet', 1, 4, 'Âm và chữ: m, n, g, gi, gh, nh, ng, ngh', 16, 'M m, N n', 'Mn', 'Học chữ m, n, đánh vần mũ, nơ', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm m hoặc âm n.","visual":{"kind":"scene","emoji":["👩","👧","🎀"],"sentence":"Mẹ mua cho Na cái nơ màu đỏ.","highlight":["mẹ","mua","na","nơ","màu"]}},{"text":"Chữ m đọc là mờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["M","m"],"say":"mờ"}},{"text":"Chữ n đọc là nờ. Chữ m có ba chân, chữ n chỉ có hai chân. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["N","n"],"say":"nờ"}},{"text":"Bé đánh vần: mờ, u, mu, ngã, mũ. Nờ, ơ, nơ.","visual":{"kind":"spell","steps":[{"parts":["m","u"],"result":"mu","say":"mờ, u, mu"},{"parts":["mu","◌̃ ngã"],"result":"mũ","say":"mu, ngã, mũ"},{"parts":["n","ơ"],"result":"nơ","say":"nờ, ơ, nơ"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🤱","word":"mẹ"},{"emoji":"🧢","word":"mũ"},{"emoji":"🎀","word":"nơ"},{"emoji":"🚤","word":"ca nô"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bố mẹ cho Na đi ca nô.","highlight":["mẹ","na","nô"]}}]'::jsonb),
('tv1-bai-17', 'tieng-viet', 1, 4, 'Âm và chữ: m, n, g, gi, gh, nh, ng, ngh', 17, 'G g, Gi gi', 'Gg', 'Học chữ g, gi, đánh vần gà, giỏ', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm g hoặc âm gi.","visual":{"kind":"scene","emoji":["👵","🧺","🐔"],"sentence":"Gió thổi nhè nhẹ, bà xách giỏ thóc ra cho gà ăn.","highlight":["gió","giỏ","gà"]}},{"text":"Chữ g đọc là gờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["G","g"],"say":"gờ"}},{"text":"Chữ gi ghép từ g và i, đọc là di. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Gi","gi"],"say":"di"}},{"text":"Bé đánh vần: gờ, a, ga, huyền, gà. Di, o, gio, hỏi, giỏ.","visual":{"kind":"spell","steps":[{"parts":["g","a"],"result":"ga","say":"gờ, a, ga"},{"parts":["ga","◌̀ huyền"],"result":"gà","say":"ga, huyền, gà"},{"parts":["gi","o"],"result":"gio","say":"di, o, gio"},{"parts":["gio","◌̉ hỏi"],"result":"giỏ","say":"gio, hỏi, giỏ"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🐔","word":"gà"},{"emoji":"🧺","word":"giỏ"},{"emoji":"🪵","word":"gỗ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Gà mổ cỏ. Bé giữ giỏ cho bà.","highlight":["gà","giữ","giỏ"]}}]'::jsonb),
('tv1-bai-18', 'tieng-viet', 1, 4, 'Âm và chữ: m, n, g, gi, gh, nh, ng, ngh', 18, 'Gh gh, Nh nh', 'Gh', 'Học chữ gh, nh, đánh vần ghế, nhà', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có chữ gh hoặc chữ nh.","visual":{"kind":"scene","emoji":["👧","🏠","🍇"],"sentence":"Bé ghé nhà bà, bà mời bé ăn nho.","highlight":["ghé","nhà","nho"]}},{"text":"Chữ gh ghép từ g và h, đọc là gờ kép. Chữ gh chỉ đứng trước i, e, ê. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Gh","gh"],"say":"gờ kép"}},{"text":"Chữ nh ghép từ n và h, đọc là nhờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Nh","nh"],"say":"nhờ"}},{"text":"Bé đánh vần: gờ kép, ê, ghê, sắc, ghế. Nhờ, a, nha, huyền, nhà.","visual":{"kind":"spell","steps":[{"parts":["gh","ê"],"result":"ghê","say":"gờ kép, ê, ghê"},{"parts":["ghê","◌́ sắc"],"result":"ghế","say":"ghê, sắc, ghế"},{"parts":["nh","a"],"result":"nha","say":"nhờ, a, nha"},{"parts":["nha","◌̀ huyền"],"result":"nhà","say":"nha, huyền, nhà"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🪑","word":"ghế"},{"emoji":"🏠","word":"nhà"},{"emoji":"🍇","word":"nho"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Nhà bà có ghế gỗ, có giỏ nho.","highlight":["nhà","ghế","nho"]}}]'::jsonb),
('tv1-bai-19', 'tieng-viet', 1, 4, 'Âm và chữ: m, n, g, gi, gh, nh, ng, ngh', 19, 'Ng ng, Ngh ngh', 'Ng', 'Học chữ ng, ngh, đánh vần ngô, nghé', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có chữ ng hoặc chữ ngh.","visual":{"kind":"scene","emoji":["👵","👧","📖"],"sentence":"Bé ngồi nghỉ ở đầu ngõ, nghe bà kể chuyện.","highlight":["ngồi","nghỉ","ngõ","nghe"]}},{"text":"Chữ ng ghép từ n và g, đọc là ngờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Ng","ng"],"say":"ngờ"}},{"text":"Chữ ngh ghép từ n, g và h, đọc là ngờ kép. Chữ ngh chỉ đứng trước i, e, ê. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Ngh","ngh"],"say":"ngờ kép"}},{"text":"Bé đánh vần: ngờ, ô, ngô. Ngờ kép, e, nghe, sắc, nghé.","visual":{"kind":"spell","steps":[{"parts":["ng","ô"],"result":"ngô","say":"ngờ, ô, ngô"},{"parts":["ngh","e"],"result":"nghe","say":"ngờ kép, e, nghe"},{"parts":["nghe","◌́ sắc"],"result":"nghé","say":"nghe, sắc, nghé"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🌽","word":"ngô"},{"emoji":"😴","word":"ngủ"},{"emoji":"🤔","word":"nghĩ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bà ngủ, bé đi nhè nhẹ cho bà nghỉ.","highlight":["ngủ","nghỉ"]}}]'::jsonb),
('tv1-bai-20', 'tieng-viet', 1, 4, 'Âm và chữ: m, n, g, gi, gh, nh, ng, ngh', 20, 'Ôn tập', 'Ôn', 'Ôn lại chữ m, n, g, gi, gh, nh, ng, ngh', '[{"text":"Bé đã học thêm tám chữ. Đây là bốn chữ đầu: m, n, g, gi. Bé bấm để nghe lại.","visual":{"kind":"letter","letters":["m","n","g","gi"],"say":"mờ, nờ, gờ, di"}},{"text":"Còn đây là bốn chữ sau: gh, nh, ng, ngh. Bé bấm để nghe lại.","visual":{"kind":"letter","letters":["gh","nh","ng","ngh"],"say":"gờ kép, nhờ, ngờ, ngờ kép"}},{"text":"Bé nhớ: gh chỉ đứng trước i, e, ê, như ghi. Còn g đứng trước a, o, ô, ơ, u, ư, như gõ.","visual":{"kind":"spell","steps":[{"parts":["gh","i"],"result":"ghi","say":"gờ kép, i, ghi"},{"parts":["g","o"],"result":"go","say":"gờ, o, go"},{"parts":["go","◌̃ ngã"],"result":"gõ","say":"go, ngã, gõ"}]}},{"text":"Ngh cũng chỉ đứng trước i, e, ê, như nghỉ. Còn ng đứng trước a, o, ô, ơ, u, ư, như ngõ.","visual":{"kind":"spell","steps":[{"parts":["ngh","i"],"result":"nghi","say":"ngờ kép, i, nghi"},{"parts":["nghi","◌̉ hỏi"],"result":"nghỉ","say":"nghi, hỏi, nghỉ"},{"parts":["ng","o"],"result":"ngo","say":"ngờ, o, ngo"},{"parts":["ngo","◌̃ ngã"],"result":"ngõ","say":"ngo, ngã, ngõ"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🧢","word":"mũ"},{"emoji":"🧺","word":"giỏ"},{"emoji":"🍇","word":"nho"},{"emoji":"🌽","word":"ngô"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bé nghỉ hè ở nhà bà. Nhà bà có gà, có ngô.","highlight":[]}}]'::jsonb),
('tv1-bai-21', 'tieng-viet', 1, 5, 'Âm và chữ: r, s, t, tr, th, ia, ua, ưa', 21, 'R r, S s', 'Rs', 'Học chữ r, s, đánh vần rổ, sổ', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm r hoặc âm s.","visual":{"kind":"scene","emoji":["🌅","👧","🌱"],"sentence":"Sáng sớm, bé theo bà ra vườn tưới rau.","highlight":["sáng","sớm","ra","rau"]}},{"text":"Chữ r đọc là rờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["R","r"],"say":"rờ"}},{"text":"Chữ s đọc là sờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["S","s"],"say":"sờ"}},{"text":"Bé đánh vần: rờ, ô, rô, hỏi, rổ. Sờ, ô, sô, hỏi, sổ.","visual":{"kind":"spell","steps":[{"parts":["r","ô"],"result":"rô","say":"rờ, ô, rô"},{"parts":["rô","◌̉ hỏi"],"result":"rổ","say":"rô, hỏi, rổ"},{"parts":["s","ô"],"result":"sô","say":"sờ, ô, sô"},{"parts":["sô","◌̉ hỏi"],"result":"sổ","say":"sô, hỏi, sổ"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🐟","word":"cá rô"},{"emoji":"📒","word":"sổ"},{"emoji":"😱","word":"sợ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bé rủ bà ra bờ hồ. Hồ có cá rô.","highlight":["rủ","ra","rô"]}}]'::jsonb),
('tv1-bai-22', 'tieng-viet', 1, 5, 'Âm và chữ: r, s, t, tr, th, ia, ua, ưa', 22, 'T t, Tr tr', 'Tt', 'Học chữ t, tr, đánh vần tô, tre', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm t hoặc âm tr.","visual":{"kind":"scene","emoji":["👦","🚗","🦁"],"sentence":"Trưa nay, bé ngồi trên ô tô đi xem sư tử.","highlight":["trưa","trên","tô","tử"]}},{"text":"Chữ t đọc là tờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["T","t"],"say":"tờ"}},{"text":"Chữ tr ghép từ t và r, đọc là trờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Tr","tr"],"say":"trờ"}},{"text":"Bé đánh vần: tờ, ô, tô. Trờ, e, tre.","visual":{"kind":"spell","steps":[{"parts":["t","ô"],"result":"tô","say":"tờ, ô, tô"},{"parts":["tr","e"],"result":"tre","say":"trờ, e, tre"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🚗","word":"ô tô"},{"emoji":"🦁","word":"sư tử"},{"emoji":"🍵","word":"trà"},{"emoji":"🎋","word":"tre"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Ở nhà trẻ, cô cho bé tô chữ.","highlight":["trẻ","tô"]}}]'::jsonb),
('tv1-bai-23', 'tieng-viet', 1, 5, 'Âm và chữ: r, s, t, tr, th, ia, ua, ưa', 23, 'Th th, ia', 'Th', 'Học chữ th và ia, đánh vần thỏ, mía', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm th hoặc âm ia.","visual":{"kind":"scene","emoji":["👧","🐰","🥕"],"sentence":"Kìa, thỏ con đang chia cà rốt cho các bạn.","highlight":["kìa","thỏ","chia"]}},{"text":"Chữ th ghép từ t và h, đọc là thờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Th","th"],"say":"thờ"}},{"text":"Ia gồm chữ i đứng trước, chữ a đứng sau. Bé bấm vào để nghe.","visual":{"kind":"letter","letters":["Ia","ia"],"say":"ia"}},{"text":"Bé đánh vần: thờ, o, tho, hỏi, thỏ. Mờ, ia, mia, sắc, mía. Dấu sắc đặt trên chữ i.","visual":{"kind":"spell","steps":[{"parts":["th","o"],"result":"tho","say":"thờ, o, tho"},{"parts":["tho","◌̉ hỏi"],"result":"thỏ","say":"tho, hỏi, thỏ"},{"parts":["m","ia"],"result":"mia","say":"mờ, ia, mia"},{"parts":["mia","◌́ sắc"],"result":"mía","say":"mia, sắc, mía"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🐰","word":"thỏ"},{"emoji":"🥄","word":"thìa"},{"emoji":"💿","word":"đĩa"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Mẹ cho bé đĩa mía, bé chia cho bà.","highlight":["đĩa","mía","chia"]}}]'::jsonb),
('tv1-bai-24', 'tieng-viet', 1, 5, 'Âm và chữ: r, s, t, tr, th, ia, ua, ưa', 24, 'ua, ưa', 'ua', 'Học ua, ưa, đánh vần cua, dừa', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm ua hoặc âm ưa.","visual":{"kind":"scene","emoji":["👧","🐢","🦀"],"sentence":"Trưa hè, bé ra biển, thấy rùa và cua bò trên cát.","highlight":["trưa","rùa","cua"]}},{"text":"Ua gồm chữ u đứng trước, chữ a đứng sau. Bé bấm vào để nghe.","visual":{"kind":"letter","letters":["Ua","ua"],"say":"ua"}},{"text":"Ưa giống ua, chỉ khác ở chữ ư có râu. Bé bấm vào để nghe.","visual":{"kind":"letter","letters":["Ưa","ưa"],"say":"ưa"}},{"text":"Bé đánh vần: cờ, ua, cua. Dờ, ưa, dưa, huyền, dừa. Dấu huyền đặt trên chữ ư.","visual":{"kind":"spell","steps":[{"parts":["c","ua"],"result":"cua","say":"cờ, ua, cua"},{"parts":["d","ưa"],"result":"dưa","say":"dờ, ưa, dưa"},{"parts":["dưa","◌̀ huyền"],"result":"dừa","say":"dưa, huyền, dừa"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🦀","word":"cua"},{"emoji":"🐢","word":"rùa"},{"emoji":"🥥","word":"dừa"},{"emoji":"🥛","word":"sữa"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Mẹ đi chợ mua cua, mua dừa.","highlight":["mua","cua","dừa"]}}]'::jsonb),
('tv1-bai-25', 'tieng-viet', 1, 5, 'Âm và chữ: r, s, t, tr, th, ia, ua, ưa', 25, 'Ôn tập', 'Ôn', 'Ôn lại chữ r, s, t, tr, th và ia, ua, ưa', '[{"text":"Bé đã học thêm r, s, t, tr, th và ia, ua, ưa. Đây là bốn chữ đầu: r, s, t, tr. Bé bấm để nghe lại.","visual":{"kind":"letter","letters":["r","s","t","tr"],"say":"rờ, sờ, tờ, trờ"}},{"text":"Còn đây là th, ia, ua, ưa. Bé bấm để nghe lại.","visual":{"kind":"letter","letters":["th","ia","ua","ưa"],"say":"thờ, ia, ua, ưa"}},{"text":"Bé nhớ: với ia, ua, ưa, dấu thanh đặt trên chữ đầu, như mía, rùa, sữa.","visual":{"kind":"spell","steps":[{"parts":["mia","◌́ sắc"],"result":"mía","say":"mia, sắc, mía"},{"parts":["rua","◌̀ huyền"],"result":"rùa","say":"rua, huyền, rùa"},{"parts":["sưa","◌̃ ngã"],"result":"sữa","say":"sưa, ngã, sữa"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🚗","word":"ô tô"},{"emoji":"🐰","word":"thỏ"},{"emoji":"🦀","word":"cua"},{"emoji":"🥥","word":"dừa"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bố mẹ cho bé đi sở thú. Sở thú có sư tử, có thỏ, có rùa.","highlight":[]}}]'::jsonb),
('tv1-bai-26', 'tieng-viet', 1, 6, 'Âm và chữ: ph, qu, v, x, y', 26, 'Ph ph, Qu qu', 'Ph', 'Học chữ ph, qu, đánh vần phở, quà', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm ph hoặc âm qu.","visual":{"kind":"scene","emoji":["👧","🎁","🍜"],"sentence":"Bé về quê, mang quà cho bà, rồi cả nhà đi ăn phở.","highlight":["quê","quà","phở"]}},{"text":"Chữ ph ghép từ p và h, đọc là phờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Ph","ph"],"say":"phờ"}},{"text":"Chữ qu ghép từ q và u, đọc là quờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Qu","qu"],"say":"quờ"}},{"text":"Bé đánh vần: phờ, ơ, phơ, hỏi, phở. Quờ, a, qua, huyền, quà.","visual":{"kind":"spell","steps":[{"parts":["ph","ơ"],"result":"phơ","say":"phờ, ơ, phơ"},{"parts":["phơ","◌̉ hỏi"],"result":"phở","say":"phơ, hỏi, phở"},{"parts":["qu","a"],"result":"qua","say":"quờ, a, qua"},{"parts":["qua","◌̀ huyền"],"result":"quà","say":"qua, huyền, quà"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🍜","word":"phở"},{"emoji":"🎁","word":"quà"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bố đưa bé ra phố, mua quà cho bà.","highlight":["phố","quà"]}}]'::jsonb),
('tv1-bai-27', 'tieng-viet', 1, 6, 'Âm và chữ: ph, qu, v, x, y', 27, 'V v, X x', 'Vx', 'Học chữ v, x, đánh vần vẽ, xe', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có âm v hoặc âm x.","visual":{"kind":"scene","emoji":["👦","🎨","🐘"],"sentence":"Bé vẽ voi, vẽ xe, vẽ cả vườn hoa xinh xinh.","highlight":["vẽ","voi","xe","vườn","xinh"]}},{"text":"Chữ v đọc là vờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["V","v"],"say":"vờ"}},{"text":"Chữ x đọc là xờ. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["X","x"],"say":"xờ"}},{"text":"Bé đánh vần: vờ, e, ve, ngã, vẽ. Xờ, e, xe.","visual":{"kind":"spell","steps":[{"parts":["v","e"],"result":"ve","say":"vờ, e, ve"},{"parts":["ve","◌̃ ngã"],"result":"vẽ","say":"ve, ngã, vẽ"},{"parts":["x","e"],"result":"xe","say":"xờ, e, xe"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"👛","word":"ví"},{"emoji":"🧳","word":"va li"},{"emoji":"🚲","word":"xe"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Nghỉ hè, cả nhà đi xe về quê.","highlight":["xe","về"]}}]'::jsonb),
('tv1-bai-28', 'tieng-viet', 1, 6, 'Âm và chữ: ph, qu, v, x, y', 28, 'Y y', 'Yy', 'Học chữ y, đánh vần quý, ý', '[{"text":"Bé bấm nghe câu. Các tiếng tô màu có chữ y.","visual":{"kind":"scene","emoji":["🏥","👩","👧"],"sentence":"Cô y tá dặn bé: chú ý ăn ngủ đủ giờ nhé.","highlight":["y","ý"]}},{"text":"Chữ y đọc là i dài. Bé bấm vào chữ để nghe.","visual":{"kind":"letter","letters":["Y","y"],"say":"i dài"}},{"text":"Bé đánh vần: quờ, i dài, quy, sắc, quý. Y thêm dấu sắc thành ý.","visual":{"kind":"spell","steps":[{"parts":["qu","y"],"result":"quy","say":"quờ, i dài, quy"},{"parts":["quy","◌́ sắc"],"result":"quý","say":"quy, sắc, quý"},{"parts":["y","◌́ sắc"],"result":"ý","say":"y, sắc, ý"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🧎","word":"quỳ"},{"emoji":"💎","word":"đá quý"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bà bị ho, cô y tá ghé nhà. Bé quý cô y tá.","highlight":["y","quý"]}}]'::jsonb),
('tv1-bai-29', 'tieng-viet', 1, 6, 'Âm và chữ: ph, qu, v, x, y', 29, 'Luyện tập chính tả', 'Ck', 'Luyện viết đúng c hay k, g hay gh, ng hay ngh', '[{"text":"Bé nhớ: k đứng trước i, e, ê, như kì đà. C đứng trước a, o, ô, ơ, u, ư, như cá.","visual":{"kind":"pictures","items":[{"emoji":"🦎","word":"kì đà"},{"emoji":"🐟","word":"cá"}]}},{"text":"Gh đứng trước i, e, ê, như ghế. G đứng trước a, o, ô, ơ, u, ư, như gà.","visual":{"kind":"pictures","items":[{"emoji":"🪑","word":"ghế"},{"emoji":"🐔","word":"gà"}]}},{"text":"Ngh đứng trước i, e, ê, như nghĩ. Ng đứng trước a, o, ô, ơ, u, ư, như ngô.","visual":{"kind":"pictures","items":[{"emoji":"🤔","word":"nghĩ"},{"emoji":"🌽","word":"ngô"}]}}]'::jsonb),
('tv1-bai-30', 'tieng-viet', 1, 6, 'Âm và chữ: ph, qu, v, x, y', 30, 'Ôn tập', 'Ôn', 'Ôn lại chữ ph, qu, v, x, y và cách viết c, k, g, gh, ng, ngh', '[{"text":"Bé đã học thêm năm chữ: ph, qu, v, x, y. Bé bấm để nghe lại.","visual":{"kind":"letter","letters":["ph","qu","v","x","y"],"say":"phờ, quờ, vờ, xờ, i dài"}},{"text":"Bé đánh vần lại: phờ, ô, phô, sắc, phố. Vờ, e, ve, sắc, vé.","visual":{"kind":"spell","steps":[{"parts":["ph","ô"],"result":"phô","say":"phờ, ô, phô"},{"parts":["phô","◌́ sắc"],"result":"phố","say":"phô, sắc, phố"},{"parts":["v","e"],"result":"ve","say":"vờ, e, ve"},{"parts":["ve","◌́ sắc"],"result":"vé","say":"ve, sắc, vé"}]}},{"text":"Bé đọc từng từ, rồi bấm vào tranh để nghe lại.","visual":{"kind":"pictures","items":[{"emoji":"🎁","word":"quà"},{"emoji":"👛","word":"ví"},{"emoji":"🚲","word":"xe"},{"emoji":"🧎","word":"quỳ"}]}},{"text":"Bé tự đọc câu này, rồi bấm loa để nghe lại.","visual":{"kind":"sentence","text":"Bố đi xe chở bé ra phố. Bé mua quà về cho bà, vì bé quý bà.","highlight":[]}}]'::jsonb)
